// air past the lens: pink noise swept up and down, loudest at 0.35 s
const n = kit.noise('pink'), bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.Q.value = 1.6;
kit.env(bp.frequency, [[0, 350], [0.35, 3200], [0.7, 500]], 'exp');
const g = ctx.createGain(); kit.env(g.gain, [[0, 0.001], [0.35, 1], [0.7, 0.001]], 'exp');
n.connect(bp).connect(g).connect(ctx.destination); n.start(0);
